#include <vector>

// Sum all values with descriptive names and a single responsibility.
int sumValues(const std::vector<int>& values) {
    int total = 0;
    for (int index = 0; index < static_cast<int>(values.size()); ++index) {
        total += values[index];
    }
    return total;
}

def sum_values(values):
    """Return the total of all input values."""
    total = 0
    for value in values:
        total += value
    return total

