#include <algorithm>
#include <vector>

// Return the largest element, or zero for an empty collection.
int maximumValue(const std::vector<int>& values) {
    if (values.empty()) {
        return 0;
    }
    return *std::max_element(values.begin(), values.end());
}

def count_positive(values):
    """Count values greater than zero without modifying the input."""
    positive_count = 0
    for value in values:
        if value > 0:
            positive_count += 1
    return positive_count

public class Main {
    // Calculate the maximum value using descriptive names.
    static int maximumValue(int[] values) {
        int maximum = values[0];
        for (int index = 1; index < values.length; index++) {
            maximum = Math.max(maximum, values[index]);
        }
        return maximum;
    }
}

#include <stddef.h>

/* Count non-zero entries in a clear, single-purpose pass. */
int count_nonzero(const int values[], size_t length) {
    int count = 0;
    for (size_t index = 0; index < length; ++index) {
        if (values[index] != 0) {
            ++count;
        }
    }
    return count;
}

